{
  "verdict": "CHANGES",
  "findings": [
    {
      "scope": "SPEC",
      "severity": "high",
      "reference": "Task Card 2–4",
      "problem": "The handoff leaves the reconciliation-to-helper transition implicit, and the acceptance matrix omits both unresolved UNKNOWN and the exact attempt limit. All three listed state scenarios can pass with this diff when tested within budget.",
      "example": "Specify the state upstream passes after reconciliation establishes non-acceptance. Require false while reconciliation is pending or confirms acceptance, true after established non-acceptance with budget remaining, and false at attemptIndex == maxAttempts."
    },
    {
      "scope": "DIFF",
      "severity": "high",
      "reference": "SendGuard.mqh, MaySend return condition",
      "problem": "The new predicate allows UNKNOWN to send before reconciliation. If the broker accepted the original order and its response was lost, this can create a duplicate order.",
      "example": "MaySend(UNKNOWN, 1, 3) must return false while reconciliation is pending. The new code returns true."
    },
    {
      "scope": "DIFF",
      "severity": "high",
      "reference": "SendGuard.mqh, MaySend attempt limit",
      "problem": "The strict greater-than check admits attemptIndex == maxAttempts, allowing one extra send beyond the configured total.",
      "example": "With maxAttempts set to 1, MaySend(READY, 0, 1) should return true and MaySend(FAILED, 1, 1) must return false. The new code returns true for both."
    }
  ]
}
